public boolean shouldPrintMessage(int timestamp, String message) {
    // Assuming a map to store the last printed timestamp for each message
    Map<String, Integer> messageTimestamps = new HashMap<>();

    // Check if the message has been printed before
    if (messageTimestamps.containsKey(message)) {
        // Get the last printed timestamp for the message
        int lastTimestamp = messageTimestamps.get(message);
        // Check if the current timestamp is at least 10 seconds greater than the last printed timestamp
        if (timestamp - lastTimestamp >= 10) {
            // Update the last printed timestamp for the message
            messageTimestamps.put(message, timestamp);
            return true;
        } else {
            return false;
        }
    } else {
        // If the message has not been printed before, print it and store the timestamp
        messageTimestamps.put(message, timestamp);
        return true;
    }
}

